package linecaps

import (
	"strings"
	"testing"

	"github.com/kimjooyoon/meta-ontology-go/internal/meta/sourcepolicy"
)

func TestGeneratedOwnershipRetainsCountsAndRoutesToSourceOwner(t *testing.T) {
	root := t.TempDir()
	writeMetricFile(t, root, "go.mod", "module owner.test/root\n\ngo 1.27.3\n")
	sources := map[string]string{
		"generated.go":   "// Code generated by gooo; DO NOT EDIT.\npackage owner\nfunc Generated()int{\n" + strings.Repeat("// retained\n", 80) + "return 17\n}\n",
		"handwritten.go": "package owner\n" + strings.Repeat("// retained\n", 80) + "func Handwritten()int{return 19}\n",
		"literal.go":     "package owner\nconst text = `//gooo:generated:start id=\"data\"`\n" + strings.Repeat("// retained\n", 80),
	}
	for name, source := range sources {
		writeMetricFile(t, root, name, source)
	}
	report, err := AnalyzeLineMetrics(root)
	if err != nil {
		t.Fatal(err)
	}
	seen := 0
	for _, indicator := range report.Meta.Indicators {
		if indicator.MetricID != sourcepolicy.DimensionGoFileLines {
			continue
		}
		seen++
		if indicator.Value != lineCount([]byte(sources[indicator.Subject])) {
			t.Fatal("size lost", indicator)
		}
		if indicator.Subject == "generated.go" {
			if indicator.IsDriverCandidate() || indicator.ApplicabilityRule != "gooo://source-ownership/resolve" || indicator.ApplicabilityReason != "GENERATED_SOURCE_OWNER_REQUIRED" {
				t.Fatal(indicator)
			}
		} else if !indicator.IsDriverCandidate() {
			t.Fatal("handwritten source became hidden", indicator)
		}
	}
	if seen != 3 || report.Total().GoFiles != 3 {
		t.Fatal("source observations lost", seen, report.Total())
	}
}
